#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Puts the alpha online on an OVHcloud VPS (issue #139): the owner's steps at the provider, the
# DNS and GitHub, plus the host's hardening (scripts/vps/prepare-host.sh, ADR 0019), the first
# deploy (ADR 0012) and `pnpm check:staging` against it. Run from anywhere in the repository:
#
#   scripts/vps/setup-vps.sh
#
# The values it asks for land in `.env.vps` (ignored by git), so a second run offers them again.
# No password or private key is kept there.

# set_environment_secret NAME VALUE sets a secret of the `production` environment, the only
# jobs that can read it (docs/deploy.md). Unlike set_secret, it stops the wizard on failure:
# the deploy cannot run without these.
set_environment_secret() {
  local name="$1" value="$2"
  printf '%s' "$value" | gh secret set "$name" --env production
  WRITTEN_SECRET+=("$name")
  printf '  %s✓ set%s production secret %s\n' "$GREEN" "$RESET" "$name"
}

run_wizard() {

TOTAL_STAGES=11
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=.env.vps
if ! { command -v gh >/dev/null && gh auth status >/dev/null 2>&1; }; then
  warn "gh is not signed in: run 'gh auth login' first."
  exit 1
fi

banner "Leyline alpha on an OVHcloud VPS"

stage "OVHcloud: the VPS"
say "The alpha needs a VPS-1 (2 vCore, 4 GB) running Ubuntu LTS, x86, in an EU data centre, or a"
say "VPS-2 if no EU location has a VPS-1: never a location outside the EU (ADR 0016)."
ask OWNER_SSH_PUBLIC_KEY "Your SSH public key file (empty: ~/.ssh/id_ed25519.pub):"
OWNER_SSH_PUBLIC_KEY=${OWNER_SSH_PUBLIC_KEY:-$HOME/.ssh/id_ed25519.pub}
if [[ ! -f "$OWNER_SSH_PUBLIC_KEY" ]]; then
  say "You have no key at $OWNER_SSH_PUBLIC_KEY yet."
  confirm "Create one there now (ssh-keygen asks for a passphrase)?" || exit 1
  ssh-keygen -t ed25519 -f "${OWNER_SSH_PUBLIC_KEY%.pub}"
fi
write_env OWNER_SSH_PUBLIC_KEY "$OWNER_SSH_PUBLIC_KEY"
if confirm "Is the VPS already ordered?"; then
  step "Control panel → Bare Metal Cloud → VPS → your VPS: check its plan,"
  step "location and architecture. Stop if one is wrong: only a new order changes them."
  step "Check it runs Ubuntu LTS; if not, reinstall it with the latest Ubuntu LTS image."
  step "Billing → My services: check it is billed monthly. Stop if a minimum commitment shows up."
  note "  Its delivery e-mail holds a secure link to the temporary password: the next stages use it."
else
  open_url "https://www.ovhcloud.com/it/vps/"
  step "Pick the plan, an EU location (France, Germany, Poland...) and the latest Ubuntu LTS image."
  step "Bill it monthly, and drop the automated backup: the catalog is rebuilt from Scryfall."
  step "In the configurator, check the monthly price has no minimum commitment and no setup fee:"
  note "  research/vps-alpha-hosting.md could not verify either. Stop if one shows up."
  step "If the order offers an SSH key, paste this one (else OVHcloud mails how to log in):"
  note "  $(cat "$OWNER_SSH_PUBLIC_KEY")"
  step "Complete the order and wait for the e-mail saying the VPS is ready."
fi
ask VPS_ADDRESS "The VPS's IPv4 address (from the e-mail or the control panel):"
write_env VPS_ADDRESS "$VPS_ADDRESS"
ask VPS_ADMIN_USER "The user the e-mail names (ubuntu on Ubuntu images):"
write_env VPS_ADMIN_USER "$VPS_ADMIN_USER"
ADMIN="$VPS_ADMIN_USER@$VPS_ADDRESS"

stage "OVHcloud: the data processing agreement"
say "The DPA is attached to OVHcloud's contracts: read it and accept it for this service."
open_url "https://www.ovhcloud.com/it/terms-and-conditions/contracts/"
step "Open 'Contratto per il trattamento dei dati' and keep a copy of the PDF."
step "If the control panel asks you to accept it, do so."
pause "Press Enter once the DPA is accepted."

stage "First login and the host's key"
say "Pin the VPS's host key, checked against its own console, before trusting it."
step "Control panel → your VPS → KVM console, log in, and run:"
note "  ssh-keygen -lf /etc/ssh/ssh_host_ed25519_key.pub"
# ssh-keyscan prints the host's public keys in known_hosts format; ssh-keygen -lf - their fingerprints.
VPS_KNOWN_HOSTS=$(ssh-keyscan -t ed25519 "$VPS_ADDRESS" 2>/dev/null)
say "The key this machine sees:"
note "  $(ssh-keygen -lf - <<<"$VPS_KNOWN_HOSTS")"
confirm "Does the fingerprint match the console's?" || { warn 'Stop: something else answers on that address.'; exit 1; }
# Only if ssh does not know the host yet: an entry already there stays as it is.
ssh-keygen -F "$VPS_ADDRESS" >/dev/null || printf '%s\n' "$VPS_KNOWN_HOSTS" >> ~/.ssh/known_hosts
# BatchMode: fail instead of asking for a password, to tell whether the key already works.
if ! ssh -o BatchMode=yes "$ADMIN" true 2>/dev/null; then
  say "Your key is not on the VPS yet. First, change the temporary password from the delivery"
  say "e-mail's secure link: OVHcloud makes the first login do that, then closes the session."
  step "In another terminal: ssh $ADMIN, type the temporary password, then a new one twice."
  pause "Press Enter once the password is changed."
  say "ssh-copy-id now adds your key, asking once for the new password."
  ssh-copy-id -i "$OWNER_SSH_PUBLIC_KEY" "$ADMIN"
fi
ssh -o BatchMode=yes "$ADMIN" true || { warn "$VPS_ADMIN_USER still cannot log in with your key."; exit 1; }
say "✓ $VPS_ADMIN_USER logs in with your key."

stage "DNS: the site's name, IPv4 only"
ask APP_DOMAIN "The site's domain (empty: leyline.website):"
write_env APP_DOMAIN "${APP_DOMAIN:-leyline.website}"
step "OVHcloud control panel → Web Cloud → Domain names → $APP_DOMAIN → DNS zone."
step "Point the A record of $APP_DOMAIN itself (subdomain '@') at $VPS_ADDRESS: edit the"
note "  default one, which points at OVHcloud's parking page, rather than adding a second."
step "Delete its AAAA record, if there is one: the alpha is IPv4 only (ADR 0016)."
step "Point the A record of www.$APP_DOMAIN (subdomain 'www') at $VPS_ADDRESS too: Caddy sends it"
note "  to $APP_DOMAIN. The zone's other default records (MX, TXT) can stay."
# `getent ahostsv4/ahostsv6` asks the system resolver for one address family.
# Every A answer, deduplicated: a parking address left beside the VPS's must not pass.
until [[ "$(getent ahostsv4 "$APP_DOMAIN" | awk '{ print $1 }' | sort -u)" == "$VPS_ADDRESS" ]] &&
  ! getent ahostsv6 "$APP_DOMAIN" | grep -qv '::ffff:'; do
  note "  $APP_DOMAIN does not resolve to $VPS_ADDRESS alone yet: a changed record can stay"
  note "  cached until its old TTL runs out."
  pause "Press Enter to look again, or Ctrl-C to stop and re-run later."
done
say "✓ $APP_DOMAIN resolves to $VPS_ADDRESS, with no IPv6 address."

stage "OVHcloud: the Edge Network Firewall"
say "The provider's firewall drops traffic before it reaches the VPS. It covers IPv4 only;"
say "ufw, set up in the next stage, covers both."
open_url "https://docs.ovhcloud.com/en/guides/bare-metal-cloud/dedicated-servers/firewall-network"
step "Control panel → Bare Metal Cloud → Network → IP addresses → $VPS_ADDRESS → Edge Firewall tab."
say "It is stateless: replies to the VPS's own traffic need rules of their own. With 'Add Rule',"
say "leaving the source IP and every unnamed port empty, add, by sequence number:"
step "0 PERMIT TCP, TCP option ESTABLISHED (replies to the VPS's own connections)"
step "1 PERMIT UDP, source port 53 (DNS replies)      2 PERMIT UDP, source port 123 (NTP replies)"
step "3 PERMIT TCP, destination port 22 (ADR 0019)    4 PERMIT TCP, destination port 80"
step "5 PERMIT TCP, destination port 443              6 PERMIT UDP, destination port 443 (HTTP/3)"
step "7 PERMIT ICMP (ping and path MTU discovery, as OVHcloud's own example keeps)"
step "19 DENY IPv4: everything the rules above do not permit"
note "  Without the replies' rules apt and the importer cannot reach the network."
step "Turn the 'Firewall enabled' switch on above the rules: it applies at once."
pause "Press Enter once it is on."

stage "Harden the VPS"
ask DEPLOY_USER "The deploy user to create (empty: deploy):"
write_env DEPLOY_USER "${DEPLOY_USER:-deploy}"
ask DEPLOY_PATH "Where the stack lives on the VPS (empty: /srv/leyline):"
write_env DEPLOY_PATH "${DEPLOY_PATH:-/srv/leyline}"
DEPLOYER="$DEPLOY_USER@$VPS_ADDRESS"
# A fresh key pair for the workflow, in a folder only this run sees; the private half goes to
# GitHub as soon as the VPS takes it, and is deleted when the wizard ends.
DEPLOY_KEY_DIR=$(mktemp -d)
trap 'rm -rf "$DEPLOY_KEY_DIR"' EXIT
# -N '': no passphrase, the runner cannot type one.
ssh-keygen -q -t ed25519 -N '' -C leyline-deploy -f "$DEPLOY_KEY_DIR/deploy_key"
say "scripts/vps/prepare-host.sh will, as root on the VPS: install Docker, create $DEPLOY_USER"
say "(with the workflow's key and yours), turn off SSH passwords and root's login, open only"
say "22, 80 and 443 in ufw, turn on unattended-upgrades and add 2 GB of swap."
warn "From then on SSH takes keys only: keep $OWNER_SSH_PUBLIC_KEY's private half safe."
confirm "Run it now?" || exit 1
scp -q scripts/vps/prepare-host.sh "$ADMIN:/tmp/prepare-host.sh"
# printf %q quotes each argument for the remote shell, keys' spaces included; -t gives sudo a
# terminal in case it asks for a password.
ssh -t "$ADMIN" "sudo bash /tmp/prepare-host.sh $(printf '%q ' \
  --admin-user "$VPS_ADMIN_USER" --deploy-user "$DEPLOY_USER" --deploy-path "$DEPLOY_PATH" \
  --deploy-key "$(cat "$DEPLOY_KEY_DIR/deploy_key.pub")" \
  --deploy-key "$(cat "$OWNER_SSH_PUBLIC_KEY")") && rm /tmp/prepare-host.sh"
# One string: ssh joins its arguments with spaces, so the format's own quotes must reach the VPS.
ssh -o BatchMode=yes "$DEPLOYER" "docker version --format 'Docker {{.Server.Version}}'" ||
  { warn "$DEPLOY_USER cannot log in or drive Docker."; exit 1; }
say "✓ $DEPLOY_USER logs in and drives Docker."
# The workflow's key goes to GitHub now: the VPS just stopped taking any earlier one.
gh api --silent --method PUT 'repos/{owner}/{repo}/environments/production'
set_environment_secret DEPLOY_SSH_KEY "$(cat "$DEPLOY_KEY_DIR/deploy_key")"
set_environment_secret DEPLOY_KNOWN_HOSTS "$VPS_KNOWN_HOSTS"

stage "The VPS's .env"
say "The database passwords are made on the VPS itself and never leave it (ADR 0012)."
if ssh "$DEPLOYER" test -e "$DEPLOY_PATH/.env"; then
  note "  $DEPLOY_PATH/.env is already there: kept as it is, since PostgreSQL reads it only once."
else
  # `\$(openssl ...)` reaches the VPS as `$(openssl ...)`, which its own shell expands into
  # `.env`: the passwords are made there and never cross the network.
  # shellcheck disable=SC2087 # $DEPLOY_PATH and $APP_DOMAIN expand here on purpose.
  ssh "$DEPLOYER" bash -s <<EOF
set -e
cd '$DEPLOY_PATH'
umask 077
cat > .env <<ENV
POSTGRES_USER=leyline
POSTGRES_PASSWORD=\$(openssl rand -hex 32)
POSTGRES_DB=leyline
LEYLINE_OWNER_PASSWORD=\$(openssl rand -hex 32)
LEYLINE_READER_PASSWORD=\$(openssl rand -hex 32)
SITE_ADDRESS=$APP_DOMAIN
PUBLISH_ADDRESS=0.0.0.0
ENV
EOF
  say "✓ wrote $DEPLOY_PATH/.env on the VPS."
fi
# Umami's password and secret (ADR 0027), added to an older `.env` too: each line only when
# missing, so a password PostgreSQL already holds never changes. `grep -q`: tests, prints nothing.
# shellcheck disable=SC2087 # $DEPLOY_PATH expands here on purpose.
ssh "$DEPLOYER" bash -s <<EOF
set -e
cd '$DEPLOY_PATH'
for name in UMAMI_DATABASE_PASSWORD UMAMI_APP_SECRET; do
  grep -q "^\$name=" .env || echo "\$name=\$(openssl rand -hex 32)" >> .env
done
EOF
say "✓ $DEPLOY_PATH/.env holds Umami's password and secret."

stage "The testers' credentials"
say "The alpha is open (ADR 0023). The testers' guard is its emergency switch: its credentials"
say "live in a file outside the repository, beside your passwords, ready for when it is needed."
ask TESTER_CREDENTIALS_FILE "Its path (empty: ~/leyline-production/tester-credentials.caddy):"
write_env TESTER_CREDENTIALS_FILE "${TESTER_CREDENTIALS_FILE:-$HOME/leyline-production/tester-credentials.caddy}"
mkdir -p "$(dirname "$TESTER_CREDENTIALS_FILE")"
[[ -f "$TESTER_CREDENTIALS_FILE" ]] || cp docker/web/tester-credentials.example.caddy "$TESTER_CREDENTIALS_FILE"
chmod 600 "$TESTER_CREDENTIALS_FILE"
# add_tester NAME: a long random password and its argon2id hash from the stack's own Caddy
# (docs/staging.md); the password is printed once, for the owner to pass on. `tail -n 1`: the
# hash is the last line, after the log of the build `run` starts with (`pull_policy: build`).
add_tester() {
  local password hash
  password=$(openssl rand -base64 33)
  hash=$(printf '%s\n' "$password" |
    docker compose run --rm --no-deps -T web caddy hash-password --algorithm argon2id | tail -n 1)
  # shellcheck disable=SC2016 # a literal prefix, not an expansion
  [[ "$hash" == '$argon2id$'* ]] || { warn "Caddy printed no hash: $hash"; exit 1; }
  printf '%s %s\n' "$1" "$hash" >> "$TESTER_CREDENTIALS_FILE"
  say "✓ $1 added. Password, shown only now: $password"
}
if ! grep -q '^check-staging ' "$TESTER_CREDENTIALS_FILE"; then
  say "pnpm check:staging signs in with a credential of its own:"
  add_tester check-staging
  step "Save it in your password manager: \`check:staging --access closed\` needs it while the guard is on."
  pause
fi
while confirm "Add a tester, for when the guard is on?"; do
  ask TESTER_NAME "Their username:"
  add_tester "$TESTER_NAME"
  step "Send it to them over a private channel."
done

stage "GitHub: the deploy's settings"
# No TESTER_CREDENTIALS: without it the deploy leaves the guard off (docs/deploy.md).
set_var DEPLOY_HOST "$VPS_ADDRESS"
set_var DEPLOY_USER "$DEPLOY_USER"
set_var DEPLOY_PATH "$DEPLOY_PATH"

stage "The first deploy"
say "DEPLOY_ENABLED=true turns the workflow on: from then on every push to main that passes"
say "CI is deployed (ADR 0012)."
confirm "Turn it on and deploy main now?" || exit 1
set_var DEPLOY_ENABLED true
latest_deploy() { gh run list --workflow deploy.yml --limit 1 --json databaseId --jq '.[0].databaseId // ""'; }
previous_run=$(latest_deploy)
gh workflow run deploy.yml --ref main
note "  waiting for GitHub to start the run..."
until run=$(latest_deploy) && [[ -n "$run" && "$run" != "$previous_run" ]]; do sleep 2; done
# --exit-status: fail the wizard if the run fails.
gh run watch --exit-status "$run"
say "✓ deployed. The importer now fills the catalog, a few minutes on the first start:"
note "  DOCKER_HOST=ssh://$DEPLOYER docker compose -p ${DEPLOY_PATH##*/} logs -f importer"
pause "Press Enter once it has finished, to check the VPS."

stage "Check the VPS"
pnpm exec playwright install chromium
# The site is open, so the check needs no credential. ${DEPLOY_PATH##*/} is its last folder,
# which Compose names the stack after (docs/deploy.md).
DOCKER_HOST="ssh://$DEPLOYER" COMPOSE_PROJECT_NAME="${DEPLOY_PATH##*/}" \
  pnpm check:staging --access open --app "https://$APP_DOMAIN"

finish
}

run_wizard "$@"; exit
